package com.eventhub.util;
import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.SecureRandom; import java.util.HexFormat;
public final class TicketSecurity{private static final SecureRandom RANDOM=new SecureRandom();private TicketSecurity(){} public static String randomToken(){byte[] b=new byte[32];RANDOM.nextBytes(b);return HexFormat.of().formatHex(b);} public static String hmac(String value,String secret){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(m.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} public static boolean safeEquals(String a,String b){return MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}}
